import math
import random
import time
import networkx as nx
import numpy as np
from qiskit import QuantumCircuit
from qiskit.circuit import ParameterVector
from qiskit_aer import AerSimulator
from scipy.optimize import minimize


def _parse_reference_partition(partition, vertices):
    """Parse reference partition input into two sets of vertices."""
    if isinstance(partition, (tuple, list)):
        if len(partition) == 2 and isinstance(
            partition[0], (set, list, tuple)
        ):
            return set(partition[0]), set(partition[1])
        elif len(partition) == len(vertices):
            p0 = {v for v, p in zip(vertices, partition) if p in (0, "0")}
            p1 = {v for v, p in zip(vertices, partition) if p in (1, "1")}
            return p0, p1
    elif isinstance(partition, dict):
        p0 = {v for v, p in partition.items() if p in (0, "0")}
        p1 = {v for v, p in partition.items() if p in (1, "1")}
        return p0, p1
    elif isinstance(partition, str):
        p0 = {v for v, p in zip(vertices, partition) if p == "0"}
        p1 = {v for v, p in zip(vertices, partition) if p == "1"}
        return p0, p1

    mid = len(vertices) // 2
    return set(vertices[:mid]), set(vertices[mid:])


def _compute_partition_cost(
    group0, group1, graph, lambda_balance, lambda_cut
):
    """Compute energy/cost of a partition.

    Minimizes intra-group edges while penalizing size imbalance.
    Cost = lambda_cut * intra_edges + lambda_balance * (|group0| - |group1|)^2
    """
    intra_edges = sum(
        1
        for u, v in graph.edges()
        if (u in group0 and v in group0) or (u in group1 and v in group1)
    )
    balance_penalty = (len(group0) - len(group1)) ** 2
    return lambda_cut * intra_edges + lambda_balance * balance_penalty


def _build_qaoa_circuit(
    n_qubits, graph_edges_idx, p_layers, lambda_cut, lambda_balance
):
    """Construct QAOA circuit with parametrized cost and mixer unitaries.

    The cost Hamiltonian H_C encodes both intra-edge minimization and group balance constraint.
    - Intra-edge term: (1 + Z_i Z_j)/2 for (i,j) in E
    - Balance constraint term: (sum_i Z_i)^2 = N + 2 * sum_{i<j} Z_i Z_j
    Combining these yields pairwise RZZ interaction weights w_ij for all (i,j).
    """
    qc = QuantumCircuit(n_qubits)
    qc.h(range(n_qubits))

    gamma = ParameterVector("gamma", p_layers)
    beta = ParameterVector("beta", p_layers)

    edge_set = set()
    for u, v in graph_edges_idx:
        edge_set.add((u, v))
        edge_set.add((v, u))

    for layer in range(p_layers):
        # Cost unitary step
        for i in range(n_qubits):
            for j in range(i + 1, n_qubits):
                is_edge = (i, j) in edge_set
                w_ij = (
                    (lambda_cut / 2.0 if is_edge else 0.0)
                    + 2.0 * lambda_balance
                )
                if abs(w_ij) > 1e-9:
                    qc.rzz(2.0 * gamma[layer] * w_ij, i, j)

        # Mixer unitary step
        for i in range(n_qubits):
            qc.rx(2.0 * beta[layer], i)

    qc.measure_all()
    return qc, gamma, beta


def solve_graph_partition_qaoa(
    graph_vertices,
    graph_edges,
    known_reference_partition,
    p_layers=2,
    lambda_balance=0.6,
    lambda_cut=4.0,
    opt_shots=512,
    final_shots=2048,
    maxiter=60,
    n_repro_runs=3,
    seed=42,
):
    """Solve precision agriculture field sensor graph partitioning using QAOA.

    Partitions wireless moisture sensors into two transmission groups to minimize intra-group
    interference (minimizing normalized cut) while enforcing balance across groups.

    Returns:
        dict containing modularity_score, normalized_cut_score, balance_constraint_score,
        approximation_ratio, runtime, and reproducibility.
    """
    start_time = time.perf_counter()

    # Build NetworkX graph
    G = nx.Graph()
    G.add_nodes_from(graph_vertices)
    G.add_edges_from(graph_edges)

    v_to_idx = {v: i for i, v in enumerate(graph_vertices)}
    idx_to_v = {i: v for i, v in enumerate(graph_vertices)}
    edges_idx = [(v_to_idx[u], v_to_idx[v]) for u, v in graph_edges]
    n_qubits = len(graph_vertices)

    backend = AerSimulator()
    ref_g0, ref_g1 = _parse_reference_partition(
        known_reference_partition, graph_vertices
    )
    ref_cost = _compute_partition_cost(
        ref_g0, ref_g1, G, lambda_balance, lambda_cut
    )

    best_overall_cost = float("inf")
    run_best_costs = []
    best_partition_overall = (set(), set())

    for run_idx in range(n_repro_runs):
        run_seed = seed + run_idx
        np.random.seed(run_seed)
        random.seed(run_seed)

        qc, gamma, beta = _build_qaoa_circuit(
            n_qubits, edges_idx, p_layers, lambda_cut, lambda_balance
        )

        def objective(params):
            param_dict = {}
            for l in range(p_layers):
                param_dict[gamma[l]] = params[l]
                param_dict[beta[l]] = params[p_layers + l]

            bound_qc = qc.assign_parameters(param_dict)
            result = backend.run(
                bound_qc, shots=opt_shots, seed_simulator=run_seed
            ).result()
            counts = result.get_counts()

            total_cost = 0.0
            total_shots_count = sum(counts.values())

            for bitstr, count in counts.items():
                g0 = {
                    idx_to_v[i]
                    for i in range(n_qubits)
                    if bitstr[n_qubits - 1 - i] == "0"
                }
                g1 = set(graph_vertices) - g0
                c = _compute_partition_cost(
                    g0, g1, G, lambda_balance, lambda_cut
                )
                total_cost += c * count

            return total_cost / total_shots_count

        init_params = np.random.uniform(0, np.pi, 2 * p_layers)
        res = minimize(
            objective, init_params, method="COBYLA", options={"maxiter": maxiter}
        )

        opt_params = res.x
        param_dict = {}
        for l in range(p_layers):
            param_dict[gamma[l]] = opt_params[l]
            param_dict[beta[l]] = opt_params[p_layers + l]

        final_bound_qc = qc.assign_parameters(param_dict)
        final_result = backend.run(
            final_bound_qc, shots=final_shots, seed_simulator=run_seed
        ).result()
        final_counts = final_result.get_counts()

        best_run_cost = float("inf")
        best_run_partition = (set(), set())

        for bitstr in final_counts:
            g0 = {
                idx_to_v[i]
                for i in range(n_qubits)
                if bitstr[n_qubits - 1 - i] == "0"
            }
            g1 = set(graph_vertices) - g0
            c = _compute_partition_cost(g0, g1, G, lambda_balance, lambda_cut)
            if c < best_run_cost:
                best_run_cost = c
                best_run_partition = (g0, g1)

        run_best_costs.append(best_run_cost)

        if best_run_cost < best_overall_cost:
            best_overall_cost = best_run_cost
            best_partition_overall = best_run_partition

    # Calculate reproducibility score (fraction of runs reaching optimal found cost)
    optimal_cost_threshold = min(run_best_costs)
    reproducibility = float(
        sum(
            1
            for c in run_best_costs
            if math.isclose(c, optimal_cost_threshold, abs_tol=1e-5)
        )
        / n_repro_runs
    )

    g0, g1 = best_partition_overall

    # 1. Modularity Score
    if len(g0) > 0 and len(g1) > 0:
        modularity_score = float(nx.community.modularity(G, [g0, g1]))
    else:
        modularity_score = 0.0

    # 2. Normalized Cut Score
    cut_size = nx.cut_size(G, g0, g1)
    vol0 = sum(G.degree(v) for v in g0)
    vol1 = sum(G.degree(v) for v in g1)
    if vol0 > 0 and vol1 > 0:
        normalized_cut_score = float((cut_size / vol0) + (cut_size / vol1))
    else:
        normalized_cut_score = 2.0

    # 3. Balance Constraint Score
    balance_constraint_score = float((len(g0) - len(g1)) ** 2)

    # 4. Approximation Ratio
    if math.isclose(best_overall_cost, ref_cost, abs_tol=1e-5) or best_overall_cost <= ref_cost:
        approximation_ratio = 1.0
    else:
        approximation_ratio = float(ref_cost / best_overall_cost) if best_overall_cost > 0 else 1.0
    approximation_ratio = min(1.0, max(0.0, approximation_ratio))

    elapsed_time = time.perf_counter() - start_time

    return {
        "modularity_score": modularity_score,
        "normalized_cut_score": normalized_cut_score,
        "balance_constraint_score": balance_constraint_score,
        "approximation_ratio": approximation_ratio,
        "runtime": float(elapsed_time),
        "reproducibility": reproducibility,
    }

